package org.sleepwell.app;
import android.content.*;import android.hardware.*;import android.os.*;import android.widget.*;import java.util.*;import java.util.function.BooleanSupplier;
/** Shared visible lux challenge. No camera, flashlight, service, permission or recording is started. */
final class LightTask implements SensorEventListener,AutoCloseable {
 final SensorManager manager;final Sensor sensor;final SharedPreferences prefs;final String key,token;final int level;final BooleanSupplier current;final Runnable complete,fallback;final TextView reading,status;final Button start;final Handler handler=new Handler(Looper.getMainLooper());LightHold hold;boolean closed,registered,delivered;long started;
 static String key(String run,int unit,int level){LightHold.target(level);return ChallengePackState.key(run,unit,level-1);}
 static boolean math(SharedPreferences p,String run,int unit,int level){return key(run,unit,level).equals(p.getString("lightTaskOwner",""))&&p.getBoolean("lightTaskMath",false);}
 LightTask(LinearLayout body,SharedPreferences prefs,String run,int unit,int level,BooleanSupplier current,Runnable complete,Runnable fallback){this.prefs=prefs;this.level=level;this.current=current;this.complete=complete;this.fallback=fallback;key=key(run,unit,level);token=UUID.randomUUID().toString();boolean prior=key.equals(prefs.getString("lightTaskOwner",""))&&prefs.getBoolean("lightTaskMath",false);if(!prefs.edit().putString("lightTaskOwner",key).putString("lightTaskToken",token).putBoolean("lightTaskMath",prior).commit())throw new IllegalStateException("Light task could not be saved");manager=body.getContext().getSystemService(SensorManager.class);sensor=manager==null?null:manager.getDefaultSensor(Sensor.TYPE_LIGHT);Design.text(body,"Find a brighter room",22,600,Design.INK);Design.text(body,"Uncover the phone’s ambient-light sensor. Keep at least "+LightHold.target(level)+" lux for 2 seconds.",14,400,Design.MUTED);Design.space(body,16);reading=Design.text(body,"— lx",44,600,Design.BROWN);reading.setContentDescription("Current challenge light reading");status=Design.text(body,"Sensor stays off until you start",13,500,Design.MUTED);status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);start=Design.button(body,"Start light check",true,this::begin);if(sensor==null){status.setText("Ambient-light sensor unavailable. Use Math instead.");start.setEnabled(false);}else if(sensor.getReportingMode()==Sensor.REPORTING_MODE_ON_CHANGE)Design.text(body,"This sensor reports changes. A fresh reading stays valid during the hold unless it changes.",12,400,Design.MUTED);Design.button(body,"Use Math instead",false,this::chooseMath);}
 boolean live(){return !closed&&!delivered&&current.getAsBoolean()&&key.equals(prefs.getString("lightTaskOwner",""))&&token.equals(prefs.getString("lightTaskToken",""));}
 void begin(){if(!live()||sensor==null)return;if(!stopSensor()){status.setText("The sensor could not stop. Retry cleanup or use Math.");return;}int mode=sensor.getReportingMode();if(mode!=Sensor.REPORTING_MODE_ON_CHANGE&&mode!=Sensor.REPORTING_MODE_CONTINUOUS){status.setText("This sensor reporting mode is unavailable. Use Math instead.");return;}hold=new LightHold(level,SystemClock.elapsedRealtimeNanos(),mode==Sensor.REPORTING_MODE_ON_CHANGE);started=SystemClock.elapsedRealtime();status.setText("Waiting for a fresh light reading…");try{registered=true;if(!manager.registerListener(this,sensor,SensorManager.SENSOR_DELAY_NORMAL,new Handler(Looper.getMainLooper()))){stopSensor();status.setText("The light sensor could not start. Retry or use Math.");return;}start.setText("Restart light check");handler.removeCallbacksAndMessages(null);handler.post(tick);}catch(RuntimeException failure){stopSensor();status.setText("Light readings are unavailable. Retry or use Math.");}}
 final Runnable tick=new Runnable(){public void run(){if(!registered||closed)return;if(!live()){stopSensor();if(hold!=null)hold.reset();status.setText("Light check paused. Start again when ready.");return;}long now=SystemClock.elapsedRealtimeNanos();if(hold.ready(now)){finish();return;}if(SystemClock.elapsedRealtime()-started>=60000||hold.last()<0&&SystemClock.elapsedRealtime()-started>=3500){stopSensor();hold.reset();status.setText("No usable fresh reading. Retry or use Math.");return;}if(Double.isFinite(hold.lux()))status.setText(hold.lux()>=hold.target?"Hold steady · "+hold.progress(now)+"%":"More light needed · target "+hold.target+" lx");handler.postDelayed(this,100);}};
 @Override public void onSensorChanged(SensorEvent event){if(!registered||hold==null||!live()||event.values.length<1)return;double value=event.values[0];if(sensor.getMaximumRange()>0&&value>sensor.getMaximumRange()){hold.reset();status.setText("Light reading is outside the sensor range. Retry or use Math.");return;}long now=SystemClock.elapsedRealtimeNanos();boolean done=hold.sample(event.timestamp,now,value,event.accuracy!=SensorManager.SENSOR_STATUS_UNRELIABLE);reading.setText(Double.isFinite(hold.lux())?String.format(java.util.Locale.getDefault(),"%.0f lx",hold.lux()):"— lx");if(done)finish();}
 @Override public void onAccuracyChanged(Sensor sensor,int accuracy){if(hold!=null&&accuracy==SensorManager.SENSOR_STATUS_UNRELIABLE){hold.reset();status.setText("Sensor accuracy is unavailable. Retry or use Math.");}}
 private void finish(){if(!live()||hold==null||!hold.ready(SystemClock.elapsedRealtimeNanos()))return;if(!stopSensor()){status.setText("Sensor cleanup failed. Retry before continuing.");return;}if(live()){delivered=true;complete.run();}}
 private void chooseMath(){if(!live())return;if(!stopSensor()){status.setText("Sensor cleanup failed. Retry before choosing Math.");return;}if(!prefs.edit().putBoolean("lightTaskMath",true).commit()){status.setText("Math alternative could not be saved. Try again.");return;}close();fallback.run();}
 private boolean stopSensor(){handler.removeCallbacksAndMessages(null);if(!registered)return true;try{manager.unregisterListener(this);registered=false;return true;}catch(RuntimeException failure){return false;}}
 boolean released(){return !registered;}
 @Override public void close(){closed=true;stopSensor();if(hold!=null)hold.reset();}
}
